import{_ as t,o as a,c as r,a0 as n}from"./chunks/framework.K3sFe4KB.js";const m=JSON.parse('{"title":"The landscape","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/landscape.md","filePath":"explanation/landscape.md"}'),l={name:"explanation/landscape.md"};function d(o,e,s,i,c,p){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="the-landscape" tabindex="-1">The landscape <a class="header-anchor" href="#the-landscape" aria-label="Permalink to &quot;The landscape&quot;">​</a></h1><p>Existing calendar tooling covers slices of the space cicada occupies — nobody has shipped the full combination. Four camps:</p><table tabindex="0"><thead><tr><th></th><th style="text-align:center;">Declarative DSL</th><th style="text-align:center;">Plan/Apply</th><th style="text-align:center;">Stable IDs + state</th><th style="text-align:center;">Drift</th><th style="text-align:center;">Multi-provider</th><th style="text-align:center;">Reusable core</th></tr></thead><tbody><tr><td><strong>cicada</strong></td><td style="text-align:center;">YAML</td><td style="text-align:center;">yes</td><td style="text-align:center;">yes</td><td style="text-align:center;">yes</td><td style="text-align:center;">via port</td><td style="text-align:center;">yes (DDD)</td></tr><tr><td>Terraform providers</td><td style="text-align:center;">HCL</td><td style="text-align:center;">yes</td><td style="text-align:center;">yes</td><td style="text-align:center;">yes</td><td style="text-align:center;">no</td><td style="text-align:center;">no</td></tr><tr><td>YAML → ICS tools</td><td style="text-align:center;">YAML/text</td><td style="text-align:center;">no</td><td style="text-align:center;">no</td><td style="text-align:center;">no</td><td style="text-align:center;">n/a</td><td style="text-align:center;">no</td></tr><tr><td>Unified SDKs</td><td style="text-align:center;">imperative</td><td style="text-align:center;">no</td><td style="text-align:center;">no</td><td style="text-align:center;">no</td><td style="text-align:center;">yes</td><td style="text-align:center;">partial</td></tr><tr><td>Calendar MCP servers</td><td style="text-align:center;">agent tools</td><td style="text-align:center;">no</td><td style="text-align:center;">no</td><td style="text-align:center;">no</td><td style="text-align:center;">yes</td><td style="text-align:center;">no</td></tr></tbody></table><h2 id="terraform-providers-for-google-calendar" tabindex="-1">Terraform providers for Google Calendar <a class="header-anchor" href="#terraform-providers-for-google-calendar" aria-label="Permalink to &quot;Terraform providers for Google Calendar&quot;">​</a></h2><p><em>sethvargo/terraform-provider-googlecalendar</em>, <em>chewnoill/terraform-provider-google-calendar</em> — closest in spirit: they apply IaC plan/apply to calendars with stable resource ids and recorded state. But they&#39;re HCL-coupled, Google-only, their core can&#39;t be reused outside Terraform&#39;s plugin model, and they&#39;re effectively dormant. cicada borrows the lifecycle and rejects the host coupling.</p><h2 id="yaml-→-ics-export-tools" tabindex="-1">YAML → ICS export tools <a class="header-anchor" href="#yaml-→-ics-export-tools" aria-label="Permalink to &quot;YAML → ICS export tools&quot;">​</a></h2><p><em>yaml2ical</em>, <em>scientific-python/yaml2ics</em>, <em>gnomon</em>, <em>timeblok</em> — declare meetings in YAML or a custom DSL, compile to <code>.ics</code>. Elegant ergonomics (gnomon&#39;s recurrence and import/merge ideas inform cicada&#39;s structured form), but <strong>export-only</strong>: no sync with a live provider, no plan/apply, no recorded state, no drift. Without stable ids mapped to remote ids, re-running creates duplicates — the fundamental failure mode.</p><h2 id="unified-calendar-sdks" tabindex="-1">Unified calendar SDKs <a class="header-anchor" href="#unified-calendar-sdks" aria-label="Permalink to &quot;Unified calendar SDKs&quot;">​</a></h2><p><em>calendar-sdk</em>, <em>recal</em>, <em>OneCal</em> — one imperative API across Google, Microsoft Graph, CalDAV. Their <code>core</code> + <code>providers/*</code> + <code>mock</code> split validates cicada&#39;s layout, but the API is CRUD-oriented: you call <code>sdk.events.create(...)</code> rather than declaring desired state and reconciling. No DSL, no plan/apply/drift lifecycle.</p><h2 id="calendar-mcp-servers" tabindex="-1">Calendar MCP servers <a class="header-anchor" href="#calendar-mcp-servers" aria-label="Permalink to &quot;Calendar MCP servers&quot;">​</a></h2><p><em>calendar-mcp</em>, <em>calendar-mcp</em> (rauf543), <em>hasna/calendar</em>, <em>mcp-calendars</em>, <em>caldav-mcp</em> — expose calendars as agent tools, but with provider logic entangled in the transport, no declarative desired state, and no reconciliation lifecycle. cicada serves MCP as a thin adapter over the same pure core the CLI drives — the interface is abstracted too, not just the provider.</p><h2 id="the-gap" tabindex="-1">The gap <a class="header-anchor" href="#the-gap" aria-label="Permalink to &quot;The gap&quot;">​</a></h2><p>No single primitive in cicada is novel. The value is the <strong>integration</strong>: a declarative YAML DSL, a plan/apply/drift lifecycle with stable ids and recorded state, and a DDD core reusable across CLI and MCP — provider-agnostic by construction through first-class capabilities. That combination is the white space.</p>',13)])])}const g=t(l,[["render",d]]);export{m as __pageData,g as default};
